import{_ as e,o as s,c as n,S as r}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"macOS下运行红警2游戏","description":"","frontmatter":{"title":"macOS下运行红警2游戏","date":"2023-12-17 11:20","comments":true,"archives":2023,"tags":["css"]},"headers":[],"relativePath":"posts/2023-12-17-macos-ra2/index.md","filePath":"posts/2023/2023-12-17-macos-ra2.md"}'),o={name:"posts/2023-12-17-macos-ra2/index.md"};function l(t,a,p,c,i,d){return s(),n("div",null,[...a[0]||(a[0]=[r(`<p>Linux 用户有钱就换 Mac，我也日常使用 Mac 电脑了。但是对于童年回忆的红警 2 游戏，我还是想在 Mac 上玩一玩。这里记录一下在 Mac 上运行红警 2 游戏的过程。</p><h2 id="下载原版红警-2-游戏" tabindex="-1">下载原版红警 2 游戏 <a class="header-anchor" href="#下载原版红警-2-游戏" aria-label="Permalink to &quot;下载原版红警 2 游戏&quot;">​</a></h2><p>网上应该有很多下载地址，我这里就不提供了。下载完之后，先使用 windows 电脑安装一下，然后把安装好的游戏文件夹拷贝到 Mac 电脑上。</p><h2 id="安装-crossover" tabindex="-1">安装 CrossOver <a class="header-anchor" href="#安装-crossover" aria-label="Permalink to &quot;安装 CrossOver&quot;">​</a></h2><p>CrossOver 是一款可以在 Mac 上运行 Windows 程序的软件，我们可以使用 CrossOver 来运行红警 2 游戏。CrossOver 有 14 天的试用期，我们可以先下载试用一下。</p><p>在 CrossOver 中，我们先创建一个 Bottle，然后在 Bottle 中复制安装好的游戏文件夹。之后再配置环境变量，让内部 OS 使用中文运行避免乱码问题，找到 Bottole 的 <code>cxbottle.conf</code></p><p>在最后的环境变量配置中添加下面的内容：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">[EnvironmentVariables]</span></span>
<span class="line"><span style="color:#6F42C1;">&quot;LC_ALL&quot;</span><span style="color:#032F62;"> =</span><span style="color:#032F62;"> &quot;zh_CN.UTF-8&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="下载游戏补丁" tabindex="-1">下载游戏补丁 <a class="header-anchor" href="#下载游戏补丁" aria-label="Permalink to &quot;下载游戏补丁&quot;">​</a></h2><p>由于红警 2 是 2000 年的游戏了，所以在现在的电脑上运行会有一些问题，我们需要下载一些补丁来修复这些问题。</p><p>下载 cnc-ddraw 补丁，并复制到游戏目录下，然后在 CrossOver 中打开 Wine Configuration，选择 Libraries，添加一个 override，然后输入 ddraw，点击添加并应用。</p><h2 id="设置分辨率" tabindex="-1">设置分辨率 <a class="header-anchor" href="#设置分辨率" aria-label="Permalink to &quot;设置分辨率&quot;">​</a></h2><p>红警 2 的默认分辨率是 800x600，这个分辨率在现在的电脑上看起来太小了，我们需要修改一下分辨率。并且开启相关的渲染优化，打开 <code>ra2.ini</code> 文件，修改成下面的内容：</p><div class="language-ini line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">[Video]</span></span>
<span class="line"><span style="color:#D73A49;">VideoBackBuffer</span><span style="color:#24292E;">=no</span></span>
<span class="line"><span style="color:#D73A49;">AllowVRAMSidebar</span><span style="color:#24292E;">=no</span></span>
<span class="line"><span style="color:#D73A49;">AllowHiResModes</span><span style="color:#24292E;">=yes</span></span>
<span class="line"><span style="color:#D73A49;">ScreenWidth</span><span style="color:#24292E;">=1728</span></span>
<span class="line"><span style="color:#D73A49;">ScreenHeight</span><span style="color:#24292E;">=1117</span></span>
<span class="line"><span style="color:#D73A49;">StretchMovies</span><span style="color:#24292E;">=no</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>上面是我的 MBP 16 寸的分辨率，如果你的电脑分辨率不一样，可以自己修改一下。修改好之后，就可以通过运行 <code>ra2.exe</code> 来启动游戏了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>M1 电脑也是可以运行老游戏的，就是需要折腾一下。希望能帮助大家回忆童年。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://www.codeweavers.com/support/wiki/mac/faq/cxoffice62_choosedifferentlanguage" target="_blank" rel="noreferrer">Set Windows application to use a different language than the OS default</a></p><p><a href="https://github.com/FunkyFr3sh/cnc-ddraw/releases" target="_blank" rel="noreferrer">cnc-ddraw</a></p><p><a href="https://www.codeweavers.com/compatibility/crossover/tips/command-and-conquer-red-alert-2-yuris-revenge/how-to-run-red-alert-2-yuris-revenge-at-full-speed" target="_blank" rel="noreferrer">How to run Red Alert 2</a></p>`,21)])])}const b=e(o,[["render",l]]);export{h as __pageData,b as default};
